#!/usr/bin/env bash
# School PA: whole app in one file. Installs or updates and keeps all data, voices and settings.
# On the Pi:  curl -sL raw.githubusercontent.com/cordietheteacher/pa/main/u.sh | bash
set -euo pipefail
REPO="cordietheteacher/pa"
PAYLOAD_SHA="c930a48bb052618c2ff5dbadccfe96c9655f0cfe1d61818c20186dc0748a9237"
# Everything is inside main() so bash reads it all before running: when piped from curl,
# the rest of this file (the packed app) is then read from stdin.
main() {
  TMP="$(mktemp -d)"
  trap 'rm -rf "$TMP"' EXIT
  if [ -f "${BASH_SOURCE[0]:-}" ]; then
    SELF="${BASH_SOURCE[0]}"         # run from a saved file (the app's Update button)
  else
    SELF="$TMP/u.sh"; cat > "$SELF"   # piped from curl: the rest of this file arrives on stdin
  fi
  sed -n '/^__PAYLOAD__$/,$p' "$SELF" | tail -n +2 | base64 -d > "$TMP/app.tgz" 2>/dev/null || true
  echo "$PAYLOAD_SHA  $TMP/app.tgz" | sha256sum -c --status || { echo "Download was damaged. Try again."; exit 1; }
  tar -xzf "$TMP/app.tgz" -C "$TMP"
  if { true </dev/tty; } 2>/dev/null; then
    bash "$TMP/school-pa/scripts/update.sh" --from "$TMP/school-pa" --repo "$REPO" --version "${PAYLOAD_SHA:0:7}" </dev/tty
  else
    bash "$TMP/school-pa/scripts/update.sh" --from "$TMP/school-pa" --repo "$REPO" --version "${PAYLOAD_SHA:0:7}"
  fi
}
main "$@"
exit 0
